import { site, products, castings, campaignTypes, feedbackCategories } from './content.js';
import { videos } from './videos.js';
import { analytics } from './analytics.js';

export const FONTS = 'https://fonts.googleapis.com/css2?family=Inter:wght@400..900&family=Noto+Sans+Georgian:wght@400..900&display=swap';
export const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const paths = {
  arrow:'<path d="M4 12h15M13 5l7 7-7 7"/>',
  external:'<path d="M7 17 17 7M6 7h11v11"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  down:'<path d="m6 9 6 6 6-6"/>',
  menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  play:'<path d="m9 5 11 7-11 7z" fill="currentColor" stroke="none"/>',
  youtube:'<path d="M21.5 7a3 3 0 0 0-2-2C17.5 4.5 12 4.5 12 4.5S6.5 4.5 4.5 5a3 3 0 0 0-2 2C2 9 2 12 2 12s0 3 .5 5a3 3 0 0 0 2 2c2 .5 7.5 .5 7.5 .5s5.5 0 7.5-.5a3 3 0 0 0 2-2c.5-2 .5-5 .5-5s0-3-.5-5Z" fill="currentColor" stroke="none"/><path d="m10 8 6 4-6 4z" fill="var(--bg)" stroke="none"/>',
  instagram:'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none"/>',
  facebook:'<path d="M14 22v-9h3l.5-4H14V7c0-1 .5-2 2-2h2V1h-3c-4 0-6 2-6 6v2H6v4h3v9z" fill="currentColor" stroke="none"/>',
  tiktok:'<path d="M14 2h3c.2 3 2 5 5 5v3c-2 0-4-.6-5-1.7V16a6 6 0 1 1-7-5.9v3.2A3 3 0 1 0 14 16z" fill="currentColor" stroke="none"/>',
  bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',
  message:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H9l-6 2 2-5.5A8.5 8.5 0 1 1 21 11.5Z"/><circle cx="8" cy="11" r=".8" fill="currentColor"/><circle cx="12" cy="11" r=".8" fill="currentColor"/><circle cx="16" cy="11" r=".8" fill="currentColor"/>',
  users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v3"/>',
  camera:'<rect x="3" y="5" width="13" height="15" rx="3"/><path d="m16 10 6-4v13l-6-4M7 2h5"/>',
  spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',
  box:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 10 9-5m-9 5L3 8m9 5v9M8 5l9 5"/>',
  flag:'<path d="M5 22V3c5-4 8 4 15 0v12c-7 4-10-4-15 0"/>',
  share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.5 10.5 7-4m-7 7 7 4"/>',
  mail:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="m3 6 9 7 9-7"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',
  check:'<path d="m5 12 4 4L20 5"/>',
};
export const icon = (name, cls='') => `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.arrow}</svg>`;
const external = 'target="_blank" rel="noopener noreferrer"';
// Smaller derivatives of the original artwork; the originals remain as the large srcset candidate.
const thumb = v => v.image.replace(/\.webp$/, '-640.webp');
const thumbSet = v => `srcset="${thumb(v)} 640w, ${v.image} 1280w"`;
const logoSmall = '/assets/hungryman-logo-360.webp';
const brand = () => `<a class="brand" href="/" aria-label="Hungryman — მთავარი"><img src="${logoSmall}" alt="Hungryman" width="360" height="331" decoding="async"></a>`;
const navItems = [['/','მთავარი'],['/shop/','Shop'],['/business/','Business'],['/participate/','მიიღე მონაწილეობა']];
const navLinks = path => navItems.map(([href,label])=>`<a href="${href}" ${path===href?'aria-current="page"':''}>${label}</a>`).join('');
const socials = () => `<div class="socials" aria-label="Hungryman-ის სოციალური ქსელები">${site.socials.map(s=>`<a href="${s.url}" ${external} aria-label="Hungryman ${s.name}">${icon(s.icon)}</a>`).join('')}</div>`;
const header = path => `<a class="skip-link" href="#main">მთავარ შინაარსზე გადასვლა</a><header class="header"><div class="container nav">${brand()}<nav class="navlinks" aria-label="მთავარი მენიუ">${navLinks(path)}</nav><div class="nav-right"><a class="button primary" href="${site.youtube}" ${external}>${icon('youtube')}<span class="youtube-label">ნახე YouTube-ზე</span></a><button class="icon-button menu-toggle" id="menu-toggle" aria-expanded="false" aria-controls="mobile-menu" aria-label="მენიუს გახსნა">${icon('menu')}</button></div></div><nav class="mobile-menu" id="mobile-menu" aria-label="მობილური მენიუ" inert>${navLinks(path)}<a href="/feedback/">გვირჩიე რამე</a></nav></header>`;
const footer = () => `<footer class="footer"><div class="container footer-main">${brand()}<nav class="footer-links" aria-label="ქვედა მენიუ"><a href="/">მთავარი</a><a href="/shop/">Shop</a><a href="/business/">Business</a><a href="/participate/">მიიღე მონაწილეობა</a><a href="${site.careers}" ${external}>Careers</a><a href="mailto:${site.businessEmail}">Contact</a></nav>${socials()}</div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Hungryman. All rights reserved.</span><span>დიდი ისტორიები. ნამდვილი ემოციები.</span></div></footer>`;
const crumb = label => `<div class="breadcrumbs"><a href="/">მთავარი</a>${icon('chevron')}<span>${label}</span></div>`;
const eyebrow = text => `<div class="eyebrow">${text}</div>`;
const campaign = (label='შენი ბრენდი. ჩვენი შემდეგი გამოწვევა.',kind='challenge') => `<div class="campaign-image"><img src="/assets/sponsor-${kind}-960.webp" srcset="/assets/sponsor-${kind}-960.webp 960w, /assets/sponsor-${kind}.webp 1672w" sizes="(max-width:600px) calc(100vw - 32px), (max-width:900px) calc(100vw - 40px), 640px" alt="${kind==='adventure'?'ორი წამყვანი მთაში — პროდუქტის ბუნებრივი ინტეგრაცია':'წითელი და ლურჯი გუნდების ბრენდირებული გამოწვევა'}" loading="lazy" decoding="async" width="1672" height="941"><span class="concept-label">საილუსტრაციო მაგალითი</span><div class="campaign-caption"><strong>${label}</strong><span>BRANDED CHALLENGE · HUNGRYMAN</span></div></div>`;
export const productCard = (p,full=false) => `<article class="product-card"><button class="product-open" data-product="${p.id}" aria-label="${escape(p.name)} — დეტალების ნახვა"><div class="product-image frame-${p.frame}" role="img" aria-label="${escape(p.name)} — პროდუქტის კონცეფცია">${full?`<span class="product-badge">${p.label}</span>`:''}<span class="product-arrow">${icon('arrow')}</span></div><div class="product-copy"><h3 class="product-title">${escape(p.name)}</h3><p class="product-price">${p.price==null?'ფასი მალე':p.price+' ₾'}${full&&p.price!=null?'<span>საორიენტაციო</span>':''}</p></div></button></article>`;
const videoCard = v => `<a class="video-item" href="${v.url}" ${external}><div class="video-thumb"><img src="${thumb(v)}" ${thumbSet(v)} sizes="(max-width:600px) calc(100vw - 32px), (max-width:900px) 50vw, 400px" alt="${escape(v.title)}" loading="lazy" decoding="async" width="1280" height="720"><span class="video-play">${icon('play')}</span><span class="video-duration">${v.duration}</span></div><h3>${escape(v.title)}</h3><p class="video-meta">HUNGRYMAN · სრული ეპიზოდი</p></a>`;
const careers = () => `<div class="container"><section class="careers-banner"><img src="${thumb(videos[0])}" ${thumbSet(videos[0])} sizes="(max-width:600px) calc(100vw - 32px), 640px" alt="Hungryman-ის გუნდი და ქართული ფეხბურთის ლეგენდები" loading="lazy" decoding="async" width="1280" height="720"><div>${eyebrow('BE PART OF HUNGRYMAN')}<h2>შემოუერთდი Hungryman-ის გუნდს</h2><p>ნახე ღია ვაკანსიები და გახდი ჩვენი გუნდის ნაწილი.</p></div><a class="button primary" href="${site.careers}" ${external}>ვაკანსიების ნახვა ${icon('arrow')}</a></section></div>`;
const feedbackCallout = () => `<div class="container bottom-feedback"><div><h2>გვირჩიე რამე</h2><p>გაქვს ვიდეოს იდეა, სურვილი ან რამე, რისი შეცვლაც გინდა?</p></div><a class="text-link" href="/feedback/">მოგვწერე ${icon('message')}</a></div>`;

function home(){return `
<section class="hero"><div class="hero-video-backdrop" aria-hidden="true"><div class="hero-video-grid">${[videos[3],videos[0],videos[1],videos[2],videos[6],videos[7],videos[4],videos[5]].map((v,i)=>`<img class="hero-video-tile" src="${thumb(v)}" alt="" width="640" height="360" loading="${i<4?'eager':'lazy'}" decoding="async">`).join('')}</div></div><div class="hero-glow"></div><i class="triangle a" aria-hidden="true"></i><i class="triangle b" aria-hidden="true"></i><i class="triangle c" aria-hidden="true"></i><div class="container hero-copy"><div class="hero-logo-frame"><img class="hero-logo" src="/assets/hungryman-logo-720.webp" srcset="${logoSmall} 360w, /assets/hungryman-logo-720.webp 720w" sizes="(max-width:600px) 176px, 340px" alt="" width="2048" height="1881" fetchpriority="high"></div><h1 class="sr-only">HUNGRYMAN</h1><p>${site.home.description}</p><div class="actions"><a class="button primary" href="${site.youtube}" ${external}>${icon('youtube')} ნახე ვიდეოები</a><a class="button secondary" href="/shop/">${icon('bag')} Shop ${icon('arrow')}</a></div></div></section>
<div class="container quick-links"><a class="quick-link" href="/shop/"><div class="merch-sneak" style="background-image:url('/assets/merch-collection.webp')"></div><div><h2>Shop ${icon('arrow')}</h2><p>Hungryman-ის ოფიციალური პროდუქტები.</p></div></a><a class="quick-link" href="/business/"><img src="/assets/sponsor-challenge-960.webp" alt="" width="600" height="300" loading="lazy" decoding="async"><div><h2>Business ${icon('arrow')}</h2><p>შენი ბრენდი ჩვენს ისტორიაში.</p></div></a><a class="quick-link" href="/participate/"><img src="${thumb(videos[3])}" alt="" width="600" height="300" loading="lazy" decoding="async"><div><h2>მონაწილეობა ${icon('arrow')}</h2><p>გახდი შემდეგი თავგადასავლის ნაწილი.</p></div></a><a class="quick-link feedback-link" href="/feedback/">${icon('message','quick-message')}<div><h2>გვირჩიე რამე ${icon('arrow')}</h2><p>შენი იდეა შეიძლება შემდეგი ვიდეო იყოს.</p></div></a></div>
<section class="shop-preview"><div class="container shop-layout"><div class="shop-intro">${eyebrow('HUNGRYMAN SHOP')}<h2>ჩვენი პროდუქტები</h2><p>Hungryman-ის ოფიციალური პროდუქტები. ჩვენი სამყაროს ნაწილი — შენთან.</p><a class="button primary" href="/shop/">ყველა პროდუქტი ${icon('arrow')}</a></div><div><div class="product-grid">${products.map(p=>productCard(p)).join('')}</div><p class="preview-note">კოლექციის კონცეფცია · საორიენტაციო ფასები · გაყიდვები მალე</p><a class="button secondary mobile-shop-link" href="/shop/">ყველა პროდუქტი ${icon('arrow')}</a></div></div></section>
<div class="stats-strip"><div class="container stats-inner"><div class="stat">${icon('youtube')}<div><strong>${site.home.subscribers}</strong><span>YouTube გამომწერი</span></div></div><div class="stat">${icon('users')}<div><strong>ერთი გუნდი</strong><span>ათასობით ისტორია</span></div></div><div class="stat">${icon('play')}<div><strong>დიდი იდეები</strong><span>ახალი თავგადასავლები</span></div></div></div></div>
<section class="section"><div class="container business-preview"><div class="business-copy">${eyebrow('BUSINESS WITH HUNGRYMAN')}<h2>შენი ბრენდი.<br>ჩვენი ისტორიის ნაწილი.</h2><p>შექმენი კამპანია, რომელსაც ასიათასობით ადამიანი ნახავს. ვაქციოთ შენი ბრენდის იდეა ისტორიად, რომელსაც მაყურებელი დაიმახსოვრებს.</p><div class="format-tags"><span>პროდუქტის ინტეგრაცია</span><span>ბრენდირებული გამოწვევა</span><span>სოციალური კამპანია</span></div><div class="actions"><a class="button secondary" href="/business/">გაიგე მეტი ${icon('arrow')}</a></div></div><div class="business-preview-images">${campaign()}${campaign("შენი ბრენდი — ჩვენი თავგადასავლის ნაწილი.","adventure")}</div></div></section>
<section class="youtube-section"><div class="container"><div class="section-head"><div>${eyebrow('JOIN THE JOURNEY')}<h2>ნახე Hungryman YouTube-ზე</h2><p>გამოწვევები, თავგადასავლები და ნამდვილი ემოციები.</p></div><a class="text-link" href="${site.youtube}/videos" ${external}>ყველა ვიდეო ${icon('external')}</a></div><div class="video-grid">${[videos[0],videos[1],videos[3]].map(videoCard).join('')}</div></div></section>
<section class="participate-preview"><div class="container participate-callout"><div>${eyebrow('BE IN THE NEXT ONE')}<h2>შემდეგ კადრში შეიძლება შენ იყო.</h2><p>თვალი ადევნე კასტინგებს და გახდი Hungryman-ის ვიდეოს მონაწილე.</p></div><a class="button secondary" href="/participate/">მიიღე მონაწილეობა ${icon('arrow')}</a></div></section>
${careers()}${feedbackCallout()}`;}

function shop(){return `<section class="page-intro"><div class="container">${crumb('Shop')}<div class="split-title"><div>${eyebrow('WEAR THE STORY')}<h1>Hungryman Shop</h1><p>Hungryman-ის ოფიციალური პროდუქტები.</p></div><span class="pill">პირველი კოლექცია · მალე</span></div></div></section><section class="shop-page"><div class="container"><div class="collection-notice">${icon('info')}<span>გაეცანი კოლექციის კონცეფციას. პროდუქტები და ფასები საილუსტრაციოა; შეკვეთა ჯერ არ არის ხელმისაწვდომი.</span></div><div class="filter-row"><div class="filters" aria-label="პროდუქტის კატეგორიები">${['ყველა',...new Set(products.map(p=>p.category)),'Limited Edition'].map((cat,i)=>`<button class="filter" data-category="${cat}" aria-pressed="${i===0}">${cat}</button>`).join('')}</div><span class="results-count" id="results-count" aria-live="polite">${products.length} პროდუქტი</span></div><div class="product-grid" id="shop-grid">${products.map(p=>productCard(p,true)).join('')}</div><div class="shop-bottom"><div><h2>რას დაამატებდი კოლექციას?</h2><p>გვირჩიე პროდუქტი, რომლის ნახვასაც Hungryman Shop-ში ისურვებდი.</p></div><a class="button secondary" href="/feedback/?category=product">გაგვიზიარე იდეა ${icon('message')}</a></div></div></section>`;}

const businessAnalytics = () => {
 const daily = Math.round(analytics.periodViews / analytics.period.days / 1000);
 const items = [
  {key:'subscribers',value:'616',unit:'ათასი',label:'YouTube გამომწერი',detail:'Hungryman-ის არხზე'},
  {key:'periodViews',value:(analytics.periodViews / 1000000).toFixed(2),unit:'მლნ',label:'ნახვა ბოლო 28 დღეში',detail:'მათ შორის, 2.7 მლნ — სრულ ვიდეოებზე'},
  {key:'lifetimeViews',value:(analytics.lifetimeViews / 1000000).toFixed(1),unit:'მლნ',label:'ჯამური ნახვა',detail:'არხის არსებობის განმავლობაში'},
  {key:'dailyViews',value:daily,unit:'ათასი',label:'საშუალო დღიური ნახვა',detail:'ბოლო 28 დღის მიხედვით'},
 ];
 return `<section class="business-analytics" aria-labelledby="analytics-title"><div class="container">
 <div class="analytics-heading"><div>${eyebrow('HUNGRYMAN ციფრებში')}<h2 id="analytics-title">ჩვენი აუდიტორია. შენი შესაძლებლობა.</h2></div><p class="analytics-period">15 აგვისტო — 11 სექტემბერი, 2026<br>ბოლო 28 დღის მაჩვენებლები</p></div>
 <dl class="analytics-metrics">${items.map(m=>`<div class="analytics-metric"><dt>${m.label}</dt><dd><span class="analytics-value" data-metric="${m.key}" data-value="${m.value}">${m.value}</span><span class="analytics-unit">${m.unit}</span></dd><p data-detail="${m.key}">${m.detail}</p></div>`).join('')}</dl>

 <p class="analytics-source">წყარო: YouTube და YouTube Studio · მოწოდებული ანალიტიკის მიხედვით. დღიური საშუალო = 2 860 551 ნახვა ÷ 28 დღე.</p>
 </div></section>`;
};

function business(){return `<section class="page-intro business-hero"><div class="container">${crumb('Business')}<div class="business-hero-grid"><div>${eyebrow('BUSINESS WITH HUNGRYMAN')}<h1>დიდი იდეები.<br>ნამდვილი ემოციები.<br><em>შენი ბრენდი.</em></h1><p>ითანამშრომლე Hungryman-თან და შექმენი კამპანია, რომელსაც ასიათასობით ადამიანი ნახავს.</p><div class="actions"><a class="button primary" href="#business-contact">ვითანამშრომლოთ ${icon('arrow')}</a><a class="button secondary" href="#formats">რეკლამის ფორმატები</a></div></div>${campaign()}</div></div></section>
${businessAnalytics()}
<section class="why-section"><div class="container"><div class="why-top"><div>${eyebrow('WHY HUNGRYMAN')}<h2>რატომ Hungryman?</h2></div><p>დიდი და აქტიური აუდიტორია, მასშტაბური გამოწვევები და ისტორიები, რომლებსაც ადამიანები ბოლომდე უყურებენ. შენი ბრენდი შეიძლება ამ გამოცდილების ნაწილი გახდეს.</p></div><div class="platforms"><div class="platform">${icon('youtube')} <span data-channel-subs>616 ათასი გამომწერი</span></div><div class="platform">${icon('play')} YouTube & Shorts</div><div class="platform">${icon('instagram')} Instagram</div><div class="platform">${icon('tiktok')} TikTok</div><div class="platform">${icon('facebook')} Facebook</div></div></div></section>
<section class="section" id="formats"><div class="container"><div class="section-head"><div>${eyebrow('FIND YOUR FORMAT')}<h2>ბრენდს თავისი ფორმატი აქვს.</h2></div></div><div class="formats-grid">${campaignTypes.map(f=>`<article class="format"><div class="format-top">${icon(f.icon)}<span>${f.number}</span></div><h3>${f.title}</h3><small>${f.en}</small><p>${f.text}</p></article>`).join('')}</div></div></section>
<section class="section visual-examples"><div class="container"><div class="section-head"><div>${eyebrow('IMAGINE YOUR BRAND HERE')}<h2>ასე შეიძლება გამოიყურებოდეს.</h2><p>შენი ბრენდის ინტეგრაციის საილუსტრაციო მაგალითები.</p></div></div><div class="example-grid">${campaign('ბრენდი მოქმედების ცენტრში.')}${campaign('შენი ბრენდი — ჩვენი თავგადასავლის ნაწილი.','adventure')}</div></div></section>
<div class="container"><section class="contact-banner" id="business-contact"><div>${eyebrow('LET’S MAKE IT HAPPEN')}<h2>მზად ხარ, ერთად შევქმნათ?</h2><p>მოგვწერე შენი ბრენდის, მიზნისა და იდეის შესახებ — ერთად ვიპოვით შესაბამის ფორმატს.</p></div><div class="contact-actions"><a class="button primary" href="mailto:${site.businessEmail}?subject=Hungryman%20-%20Business">თანამშრომლობისთვის მოგვწერე ${icon('mail')}</a><a class="email-link" href="mailto:${site.businessEmail}">${site.businessEmail}</a></div></section></div>`;}

function castingCard(c){return `<article class="casting-card"><img src="${escape(c.cover)}" alt="${escape(c.title)}" loading="lazy" decoding="async"><div class="body"><h2>${escape(c.title)}</h2><p>${escape(c.description)}</p><div class="casting-meta">${escape(c.dateLabel)}${c.minimumAge?` · ${c.minimumAge}+`:''}</div><p>${escape(c.requirements)}</p><a class="button primary" href="${escape(c.applicationUrl)}">მონაწილეობა ${icon('arrow')}</a></div></article>`;}
function participate(){return `<section class="page-intro"><div class="container">${crumb('მიიღე მონაწილეობა')}${eyebrow('YOUR NEXT ADVENTURE')}<h1>მიიღე მონაწილეობა</h1><p>გახდი Hungryman-ის ვიდეოს ნაწილი. შენი შემდეგი თავგადასავალი შეიძლება აქ დაიწყოს.</p></div></section><div class="container"><div id="live-castings" aria-live="polite"><p class="casting-loading">კასტინგები იტვირთება…</p></div><div class="participate-footer"><p>გაქვს განსხვავებული უნარი ან ვიდეოს იდეა?<br>შეგიძლია ახლავე გაგვიზიარო.</p><a class="text-link" href="/feedback/">გვირჩიე რამე ${icon('arrow')}</a></div></div><dialog id="application-dialog" class="application-dialog"><button class="application-close icon-button" type="button" aria-label="დახურვა">${icon('close')}</button><div id="application-content"></div></dialog>`;}


function feedback(){return `<section class="feedback-page"><div class="container">${crumb('გვირჩიე რამე')}<div class="feedback-layout"><div class="feedback-copy">${eyebrow('YOUR IDEAS MATTER')}<h1>გვირჩიე რამე.<br><span>გისმენთ.</span></h1><p>გაქვს ვიდეოს იდეა, სურვილი ან რამე, რისი შეცვლაც გინდა? მოგვწერე.</p><div class="message-art">${icon('message')}</div><p class="quiet">სახელისა და ელფოსტის მითითება სურვილისამებრ შეგიძლია.</p></div><div class="form-panel"><h2>გაგვიზიარე შენი იდეა</h2><form id="feedback-form"><div class="field-row"><div class="field"><label for="feedback-name">სახელი <small>არასავალდებულო</small></label><input id="feedback-name" name="name" type="text" autocomplete="name" maxlength="100" placeholder="შენი სახელი"></div><div class="field"><label for="feedback-email">ელფოსტა <small>არასავალდებულო</small></label><input id="feedback-email" name="email" type="email" autocomplete="email" maxlength="254" placeholder="name@example.com"></div></div><fieldset class="field category-field"><legend class="field-label">რისი გაზიარება გინდა?</legend><div class="category-choices">${feedbackCategories.map((c,i)=>`<label class="category-choice"><input type="radio" name="category" value="${c}" ${i===0?'checked':''}><span>${c}</span></label>`).join('')}</div></fieldset><div class="field"><label for="feedback-message">შეტყობინება <span aria-hidden="true">*</span></label><textarea id="feedback-message" name="message" required minlength="1" maxlength="3000" placeholder="დაწერე შენი იდეა აქ…" aria-describedby="message-help message-count"></textarea><div class="message-meta"><span id="message-help">სავალდებულო ველი</span><span id="message-count">0 / 3000</span></div></div><p class="form-mode">შეტყობინებას Hungryman-ის გუნდი მიიღებს. სურვილის შემთხვევაში მიუთითე ელფოსტა, რომ დაგიკავშირდეთ.</p><div class="form-result" id="form-result" role="status" tabindex="-1" hidden></div><button class="button primary full" type="submit">გაგზავნა ${icon('arrow')}</button></form></div></div></div></section>`;}

const pages = {'/':{title:'Hungryman — ოფიციალური საიტი',description:site.home.description,render:home},'/shop/':{title:'Hungryman Shop — ოფიციალური პროდუქტები',description:'Hungryman-ის მაისურები, ჰუდები, ქუდები და საკოლექციო პროდუქტები.',render:shop},'/business/':{title:'Business with Hungryman — პარტნიორობა',description:'ითანამშრომლე Hungryman-თან. ბრენდირებული გამოწვევები, პროდუქტების ინტეგრაცია და სოციალური კამპანიები.',render:business},'/participate/':{title:'მიიღე მონაწილეობა — Hungryman',description:'Hungryman-ის ვიდეოების მონაწილეთა მიმდინარე კასტინგები.',render:participate},'/feedback/':{title:'გვირჩიე რამე — Hungryman',description:'გაგვიზიარე ვიდეოს ან პროდუქტის იდეა და შენი მოსაზრება Hungryman-ის შესახებ.',render:feedback}};
export function renderPage(path){const p=pages[path];if(!p)throw new Error(`Unknown route: ${path}`);return `<!doctype html><html lang="ka"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#020d17"><meta name="description" content="${escape(p.description)}"><meta name="robots" content="noindex,nofollow"><title>${p.title}</title><link rel="icon" href="/assets/favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="48x48" href="/assets/favicon-48.png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="${FONTS}"><link rel="stylesheet" href="/styles.css?v=perf-13"><script type="module" src="/app.js?v=perf-13"></script>${['content','views','videos','analytics'].map(m=>`<link rel="modulepreload" href="/${m}.js">`).join('')}</head><body data-page="${path}">${header(path)}<main id="main">${p.render()}</main>${footer()}<dialog id="product-dialog" class="product-dialog" aria-labelledby="product-dialog-title"></dialog><div id="toast" class="toast" role="status" hidden></div></body></html>`;}
